3	import { For, Show, type JSX } from 'solid-js';
4	import { useTerminalDimensions } from '@opentui/solid';
5	import type { ScopeId, SkillRecord } from '../types.ts';
6	import type { SearchSkill } from '../install.ts';
7	import { COLORS, HintLine, Spinner, fit, formatInstalls } from './common.tsx';
8	
9	export interface ConfirmModal {
10	  type: 'confirm';
11	  title: string;
12	  lines: string[];
13	  offset: number;
14	  action: () => Promise<void>;
15	}
16	
17	export interface ForkModal {
18	  type: 'fork';
19	  skill: SkillRecord;
20	  value: string;
21	}
22	
23	export interface SearchModal {
24	  type: 'search';
25	  scope: ScopeId;
26	  phase: 'query' | 'results';
27	  query: string;
28	  results: SearchSkill[];
29	  index: number;
30	  loading: boolean;
31	  loadingMore: boolean;
32	  hasMore: boolean;
33	  message: string;
34	  preview: string;
35	  previewFile: string;
36	  previewState: 'idle' | 'loading' | 'ready' | 'error';
37	  previewOffset: number;
38	}
39	
40	export type Modal = ConfirmModal | ForkModal | SearchModal;
41	
42	export function modalGeometry(
43	  terminalWidth: number,
44	  terminalHeight: number
45	): { left: number; top: number; width: number; height: number } {
46	  // Integer rows and columns: fractional percentage layout rounds pane heights
47	  // up while flooring child offsets, which makes footers overlap pane borders.
48	  const width = Math.max(40, Math.floor(terminalWidth * 0.8));
49	  const height = Math.max(10, Math.floor(terminalHeight * 0.7));
50	  return {
51	    left: Math.max(0, Math.floor((terminalWidth - width) / 2)),
52	    top: Math.max(1, Math.floor((terminalHeight - height) / 2)),
53	    width,
54	    height,
55	  };
56	}
57	
58	export function ModalFrame(props: { title: string; danger: boolean; children: JSX.Element }) {
59	  const dimensions = useTerminalDimensions();
60	  const geometry = () => modalGeometry(dimensions().width, dimensions().height);
61	  return (
62	    <>
63	      <box
64	        position="absolute"
65	        left={0}
66	        top={0}
67	        width="100%"
68	        height="100%"
69	        zIndex={10}
70	        backgroundColor={COLORS.backdrop}
71	      />
72	      <box
73	        position="absolute"
74	        left={geometry().left}
75	        top={geometry().top}
76	        width={geometry().width}
77	        height={geometry().height}
78	        zIndex={20}
79	        flexDirection="column"
80	        border={true}
81	        borderStyle="double"
82	        borderColor={props.danger ? COLORS.danger : COLORS.active}
83	        backgroundColor="#0c0e13"
84	        title={props.title}
85	        titleColor={props.danger ? COLORS.danger : COLORS.active}
86	        padding={1}
87	        overflow="hidden"
88	      >
89	        {props.children}
90	      </box>
91	    </>
92	  );
93	}
94	
95	function modalTitle(modal: Modal): string {
96	  if (modal.type === 'search') return `Install in ${modal.scope} scope`;
97	  if (modal.type === 'fork') return `Fork ${modal.skill.folderName}`;
98	  return modal.title;
99	}
100	
101	/** Frames the open modal and picks the view its type and phase call for. */
102	export function ModalHost(props: { modal: Modal; projectEnabled: boolean }) {
103	  const body = () => {
104	    const modal = props.modal;
105	    if (modal.type === 'confirm') return <ConfirmView modal={modal} />;
106	    if (modal.type === 'fork') return <ForkView modal={modal} />;
107	    return modal.phase === 'query' ? (
108	      <SearchQueryView modal={modal} />
109	    ) : (
110	      <SearchResultsView modal={modal} projectEnabled={props.projectEnabled} />
111	    );
112	  };
113	
114	  return (
115	    <ModalFrame title={modalTitle(props.modal)} danger={props.modal.type === 'confirm'}>
116	      {body()}
117	    </ModalFrame>
118	  );
119	}
120	
121	/** Visible search-result rows after the modal chrome and the status line. */
122	export function searchResultsCapacity(terminalWidth: number, terminalHeight: number): number {
123	  return Math.max(4, modalGeometry(terminalWidth, terminalHeight).height - 10);
124	}
125	
126	/** Inner height of a modal after the frame's border and padding. */
127	function useModalBodyHeight(): () => number {
128	  const dimensions = useTerminalDimensions();
129	  return () => modalGeometry(dimensions().width, dimensions().height).height - 4;
130	}
131	
132	export function ConfirmView(props: { modal: ConfirmModal }) {
133	  const bodyHeight = useModalBodyHeight();
134	  const capacity = () => Math.max(3, bodyHeight() - 5);
135	  const rows = () =>
136	    props.modal.lines
137	      .slice(props.modal.offset, props.modal.offset + capacity())
138	      .map((line, offset) => ({ index: props.modal.offset + offset, line }));
139	  const remaining = () => props.modal.lines.length - props.modal.offset - capacity();
140	
141	  return (
142	    <>
143	      <box flexGrow={1} minHeight={0} flexDirection="column" overflow="hidden">
144	        <Show when={props.modal.offset > 0}>
145	          <text height={1} fg={COLORS.dim}>{`↑ ${props.modal.offset} more`}</text>
146	        </Show>
147	        <For each={rows()}>
148	          {(row) => (
149	            <text height={1} fg={row.index === 0 ? COLORS.dim : COLORS.text}>
150	              {row.line}
151	            </text>
152	          )}
153	        </For>
154	        <Show when={remaining() > 0}>
155	          <text height={1} fg={COLORS.dim}>{`↓ ${remaining()} more`}</text>
156	        </Show>
157	      </box>
158	      <HintLine
159	        hints={[
160	          ['y', 'confirm'],
161	          ['n', 'cancel'],
162	          ['j/k', 'scroll'],
163	        ]}
164	      />
165	    </>
166	  );
167	}
168	
169	export function ForkView(props: { modal: ForkModal }) {
170	  return (
171	    <>
172	      <box flexGrow={1} flexDirection="column">
173	        <text fg={COLORS.dim}>The source remains tracked. The new copy is local.</text>
174	        <box height={1} />
175	        <text>
176	          <span style={{ fg: COLORS.dim }}>{'Name: '}</span>
177	          <span style={{ fg: COLORS.text }}>{props.modal.value}</span>
178	          <span style={{ fg: COLORS.active }}>_</span>
179	        </text>
180	      </box>
181	      <HintLine
182	        hints={[
183	          ['Enter', 'fork'],
184	          ['Esc', 'cancel'],
185	        ]}
186	      />
187	    </>
188	  );
189	}
190	
191	export function SearchQueryView(props: { modal: SearchModal }) {
192	  return (
193	    <>
194	      <box flexGrow={1} flexDirection="column">
195	        <text>
196	          <span style={{ fg: COLORS.dim }}>{'Search: '}</span>
197	          <span style={{ fg: COLORS.text }}>{props.modal.query}</span>
198	          <span style={{ fg: COLORS.active }}>_</span>
199	        </text>
200	        <box height={1} />
201	        <text truncate={true}>
202	          <Spinner active={props.modal.loading} />
203	          <span style={{ fg: COLORS.dim }}>{props.modal.message}</span>
204	        </text>
205	      </box>
206	      <HintLine
207	        hints={[
208	          ['Enter', 'search'],
209	          ['Backspace', 'delete'],
210	          ['Esc', 'close'],
211	        ]}
212	      />
213	    </>
214	  );
215	}
216	
217	export function SearchResultsView(props: { modal: SearchModal; projectEnabled?: boolean }) {
218	  const dimensions = useTerminalDimensions();
219	  const bodyHeight = useModalBodyHeight();
220	  const capacity = () => Math.max(4, bodyHeight() - 6);
