    const bindings = createKeyBindings({
      modal: () => activeModal,
      quit: () => quitCalls++,
    } as unknown as KeyBindingsDeps);

    bindings(key);

    expect(quitCalls).toBe(1);
    expect(key.defaultPrevented).toBe(true);
  });
});

